import XCTest

final class ChatUITests: XCTestCase {
    func testOpenChat() throws {
        let udid = "BF79EEE1-EBF7-4EA3-B636-C38EC9D6C959"
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()

        var tapped = false
        for _ in 0..<20 {
            let q = app.descendants(matching: .any).matching(
                NSPredicate(format: "label CONTAINS[cd] 'chat' OR label CONTAINS[cd] 'message' OR label CONTAINS[cd] 'dm'")
            )
            if q.count > 0 {
                let el = q.firstMatch
                if el.waitForExistence(timeout: 2) && el.isHittable {
                    el.tap()
                    tapped = true
                    break
                }
            }
            sleep(1)
        }

        if !tapped {
            let p = Process()
            p.executableURL = URL(fileURLWithPath: "/usr/bin/xcrun")
            p.arguments = ["simctl", "openurl", udid, "bluesky://messages"]
            try? p.run()
            p.waitUntilExit()
            let sb = XCUIApplication(bundleIdentifier: "com.apple.springboard")
            let open = sb.buttons["Open"]
            if open.waitForExistence(timeout: 10) {
                open.tap()
                tapped = true
            }
        }

        if !tapped {
            try? app.debugDescription.write(toFile: "/tmp/chattest-debug.txt", atomically: true, encoding: .utf8)
        }
        XCTAssertTrue(tapped, "could not open chat")
        sleep(4)
    }
}

